<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Meet the Wire Wranglers, a Paderborn engineering team untangling the future of software and AI.">
  <title>Team The Wire Wranglers | Agentic SE Lab</title>
  <script>
    (function () {
      try {
        const saved = localStorage.getItem("upb-theme");
        const theme = saved || (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
        document.documentElement.setAttribute("data-theme", theme);
      } catch (error) {
        document.documentElement.setAttribute(
          "data-theme",
          window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"
        );
      }
    })();
  </script>
  <style>
    :root {
      --bg: #FFF8E7;
      --text: #1D1D1F;
      --secondary: #5A5A5F;
      --card: #FFFFFF;
      --accent: #E4007C;
      --border: #343454;
      --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
      color-scheme: light;
    }

    :root[data-theme="dark"] {
      --bg: #14142B;
      --text: #F4F1DE;
      --secondary: #B8B5A7;
      --card: #1F1F3D;
      --border: #343454;
      --shadow: none;
      color-scheme: dark;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      font-size: 1rem;
      line-height: 1.65;
      transition: background-color 180ms ease, color 180ms ease;
    }

    a {
      color: var(--accent);
      text-underline-offset: 0.2em;
    }

    a:focus-visible,
    button:focus-visible {
      outline: 0.2rem solid var(--accent);
      outline-offset: 0.2rem;
    }

    .site-header {
      border-bottom: 1px solid var(--border);
      background: var(--bg);
    }

    .header-inner,
    main,
    .footer-inner {
      width: min(100% - 3rem, 68rem);
      margin-inline: auto;
    }

    .header-inner {
      padding-block: 1.5rem 1.25rem;
    }

    .header-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1.5rem;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 0.25rem;
      font-size: clamp(2rem, 5vw, 3.25rem);
      line-height: 1.12;
      letter-spacing: -0.04em;
    }

    .tagline {
      max-width: 42rem;
      margin-bottom: 0;
      color: var(--secondary);
      font-size: 1.1rem;
    }

    #theme-toggle {
      flex: 0 0 auto;
      min-width: 3rem;
      min-height: 3rem;
      padding: 0.5rem;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: var(--card);
      color: var(--text);
      font: inherit;
      font-size: 1.35rem;
      cursor: pointer;
    }

    .site-nav {
      display: flex;
      flex-wrap: wrap;
      gap: 1.25rem;
      margin-top: 1.1rem;
      font-size: 0.95rem;
    }

    main {
      padding-block: 2.5rem 4rem;
    }

    section + section {
      margin-top: 3.5rem;
    }

    .section-heading {
      margin-bottom: 0.4rem;
      font-size: clamp(1.6rem, 4vw, 2.2rem);
      line-height: 1.2;
      letter-spacing: -0.025em;
    }

    .section-intro {
      max-width: 46rem;
      margin-bottom: 1.5rem;
      color: var(--secondary);
    }

    .member-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      gap: 1.5rem;
      max-width: 52rem;
    }

    .member-card {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.75rem;
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    :root[data-theme="dark"] .member-card {
      border: 1px solid var(--border);
    }

    .member-card img {
      display: block;
      width: 8rem;
      height: 8rem;
      margin-bottom: 1rem;
      border-radius: 50%;
      object-fit: cover;
    }

    :root[data-theme="dark"] .member-card img {
      filter: brightness(0.9);
    }

    .member-card h3 {
      margin-bottom: 0.2rem;
      font-size: 1.5rem;
      line-height: 1.25;
    }

    .study {
      margin-bottom: 1rem;
      color: var(--secondary);
      font-size: 0.95rem;
    }

    .bio {
      margin-bottom: 0.8rem;
    }

    .outlook {
      margin: 0 0 1rem;
    }

    .fun-fact {
      margin: 0 0 1.25rem;
      color: var(--secondary);
    }

    .hot-take {
      align-self: stretch;
      margin: auto 0 0;
      padding: 0.8rem 1rem;
      border-radius: 0.65rem;
      background: var(--accent);
      color: #FFFFFF;
      font-weight: 700;
    }

    .future-panel {
      max-width: 52rem;
      padding: 1.75rem;
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    :root[data-theme="dark"] .future-panel {
      border: 1px solid var(--border);
    }

    .future-panel p:last-child {
      margin-bottom: 0;
    }

    .footer-inner {
      padding-block: 1.5rem;
      border-top: 1px solid var(--border);
      color: var(--secondary);
      text-align: center;
      font-size: 0.875rem;
    }

    .footer-inner p {
      margin: 0;
    }

    @media (max-width: 700px) {
      .header-inner,
      main,
      .footer-inner {
        width: calc(100% - 2rem);
      }

      .header-top {
        flex-direction: column;
        align-items: flex-start;
      }

      #theme-toggle {
        align-self: flex-end;
        margin-top: -0.25rem;
      }

      .site-nav {
        margin-top: 1rem;
      }

      main {
        padding-top: 2rem;
      }

      .member-card,
      .future-panel {
        padding: 1.25rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="header-top">
        <div>
          <h1>The Wire Wranglers</h1>
          <p class="tagline">One engineer, many wires, and a healthy suspicion of code that looks too confident.</p>
        </div>
        <button id="theme-toggle" type="button" aria-label="Switch to night mode">🌙</button>
      </div>
      <nav class="site-nav" aria-label="Main navigation">
        <a href="#team">Meet the team</a>
        <a href="#future-of-se">Our view of the future</a>
      </nav>
    </div>
  </header>

  <main>
    <section id="team" aria-labelledby="team-heading">
      <h2 class="section-heading" id="team-heading">Meet the team</h2>
      <p class="section-intro">A compact crew with a big interest in making intelligent tools useful—and making sure the wires are plugged in first.</p>

      <div class="member-grid">
        <article class="member-card">
          <img src="{{image:sarpesh.jpg}}" alt="Photo of Sarpesh">
          <h3>Sarpesh</h3>
          <p class="study">M.Sc. Electrical Systems Engineering, 3rd semester · Paderborn University</p>
          <p class="bio">Sarpesh is pursuing an M.Sc. in Electrical Systems Engineering at Paderborn University, where embedded systems and power electronics meet automation and control. He’s also exploring how AI tools can speed up engineering work. He sees today’s coding agents as handy assistants for boilerplate, scripts, and unfamiliar code—but their confident mistakes mean every change still needs human review and testing. In his view, the engineer’s job is not disappearing; it’s getting more interesting (and more responsible).</p>
          <p class="outlook"><strong>Next 5–10 years:</strong> Engineers will spend less time typing and more time specifying, reviewing, and verifying agent-generated work. Deep domain knowledge will matter even more when correctness and safety are on the line.</p>
          <p class="fun-fact"><em>Fun fact: He spends more time debugging wiring than code, and the wiring usually wins.</em></p>
          <p class="hot-take">🔥 Code you can’t verify isn’t a shortcut; it’s a bug with express shipping.</p>
        </article>
      </div>
    </section>

    <section id="future-of-se" aria-labelledby="future-heading">
      <h2 class="section-heading" id="future-heading">The Future of Software Engineering</h2>
      <div class="future-panel">
        <p>We see AI as a capable assistant, not an autopilot. Today it can speed up routine coding and help engineers navigate unfamiliar territory, but confident output is not the same thing as correct output. Review, testing, and understanding the whole system remain essential.</p>
        <p>Over the next 5–10 years, more of the typing may be delegated to agents; people will increasingly define what should be built, check what was built, and verify that it behaves safely in the real world. The more automated code generation becomes, the more valuable human judgment and domain expertise will be. Especially when the “system” includes actual wires.</p>
      </div>
    </section>
  </main>

  <footer>
    <div class="footer-inner">
      <p>Built by an agent, supervised by humans. <span id="year"></span> · The Wire Wranglers</p>
    </div>
  </footer>

  <script>
    (function () {
      const root = document.documentElement;
      const toggle = document.getElementById("theme-toggle");
      const year = document.getElementById("year");

      function updateToggle() {
        const isDark = root.getAttribute("data-theme") === "dark";
        toggle.textContent = isDark ? "☀️" : "🌙";
        toggle.setAttribute("aria-label", isDark ? "Switch to day mode" : "Switch to night mode");
      }

      updateToggle();
      year.textContent = new Date().getFullYear();

      toggle.addEventListener("click", function () {
        const nextTheme = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        root.setAttribute("data-theme", nextTheme);
        try {
          localStorage.setItem("upb-theme", nextTheme);
        } catch (error) {
          // Theme switching still works for this visit if storage is unavailable.
        }
        updateToggle();
      });
    })();
  </script>
</body>
</html>
